function traduzirFrase(frase) {
  // Remove o ponto final para que capturas gulosas (.+) não o incluam.
  const texto = frase.trim().replace(/\.$/, '');
  if (!texto) return '';
  // "Uncaught (in promise) TypeError: ..." -> traduz a mensagem e explica o prefixo.
  const prefixo = /^Uncaught \(in promise\)\s+(.+)$/i.exec(texto);
  if (prefixo) {
    const r = traduzirFrase(prefixo[1]);
    return r ? `Erro não tratado numa Promise (faltou try/catch ou .catch()): ${r}` : null;
  }
  for (const [regex, traducao] of regras) {
    const m = texto.match(regex);
    if (!m) continue;
    if (typeof traducao === 'function') {
      const r = traducao(...m.slice(1), traduzirLocal);
      if (r) return r;
      continue;
    }
    return traducao.replace(/\$(\d)/g, (_, i) => m[Number(i)] ?? '');
  }
  // "AlgumTipoError: mensagem" sem regra própria: traduz a mensagem e informa o tipo.
  const comTipo = /^(?:Uncaught )?([A-Z][A-Za-z]*(?:Error|Exception)|Error)(?: \[[A-Z_0-9]+\])?: (.+)$/.exec(texto);
  if (comTipo) {
    const r = traduzirLocal(comTipo[2]);
    if (r) return `${NOMES_DOS_TIPOS[comTipo[1]] ?? comTipo[1]}: ${r}`;
  }
  return null;
}

const NOMES_DOS_TIPOS = {
  SyntaxError: 'Erro de sintaxe', ReferenceError: 'Erro de referência', TypeError: 'Erro de tipo',
  RangeError: 'Erro de intervalo', URIError: 'Erro de URI', Error: 'Erro', NameError: 'Erro de nome',
  ValueError: 'Erro de valor', AttributeError: 'Erro de atributo', IndentationError: 'Erro de indentação',
};

/** Traduz uma linha usando o dicionário. Retorna null se não souber. */
function traduzirLocal(linha) {
  const inteira = traduzirFrase(linha);
  if (inteira !== null) return inteira;
  // Tenta frase por frase: "Cannot find name 'x'. Did you mean 'y'?"
  const frases = linha.split(/(?<=[.?!])\s+(?=[A-Z])/);
  if (frases.length < 2) return null;
  const partes = frases.map(traduzirFrase);
  return partes.every((p) => p !== null) ? partes.join(' ') : null;
}

